613	+
614	+/**
615	+ * {@link DiffFromHistoryHandler#showDiff(FilePath, VcsFileRevision, VcsFileRevision) "Show Diff" for 2 revision} calls the common code.
616	+ * {@link DiffFromHistoryHandler#showDiff(AnActionEvent, FilePath, VcsFileRevision) "Show diff" for 1 revision}
617	+ * behaves differently for merge commits: for them it shown a popup displaying the parents of the selected commit. Selecting a parent
618	+ * from the popup shows the difference with this parent.
619	+ * If an ordinary (not merge) revision with 1 parent, it is the same as usual: just compare with the parent;
620	+ *
621	+ * @author Kirill Likhodedov
622	+ */
623	+class GitDiffFromHistoryHandler implements DiffFromHistoryHandler {
624	+  
625	+  private static final Logger LOG = Logger.getInstance(GitDiffFromHistoryHandler.class);
626	+
627	+  @NotNull private final Project myProject;
628	+  @NotNull private final Git myGit;
629	+  @NotNull private final GitRepositoryManager myRepositoryManager;
630	+
631	+  GitDiffFromHistoryHandler(@NotNull Project project) {
632	+    myProject = project;
633	+    myGit = ServiceManager.getService(project, Git.class);
634	+    myRepositoryManager = GitUtil.getRepositoryManager(project);
635	+  }
636	+
637	+  @Override
638	+  public void showDiff(@NotNull AnActionEvent e, @NotNull FilePath filePath, @NotNull VcsFileRevision revision) {
639	+    GitFileRevision rev = (GitFileRevision)revision;
640	+    Collection<String> parents = rev.getParents();
641	+    if (parents.size() < 2) {
642	+      showDiffWithParent(revision, filePath, parents);
643	+    }
644	+    else { // merge 
645	+      showDiffForMergeCommit(e, filePath, rev, parents);
646	+    }
647	+  }
648	+
649	+  @Override
650	+  public void showDiff(@NotNull FilePath filePath, @NotNull VcsFileRevision revision1, @NotNull VcsFileRevision revision2) {
651	+    doShowDiff(filePath, revision1, revision2, true);
652	+  }
653	+
654	+  private void doShowDiff(@NotNull FilePath filePath, @NotNull VcsFileRevision revision1, @NotNull VcsFileRevision revision2,
655	+                          boolean autoSort) {
656	+    VcsHistoryUtil.showDifferencesInBackground(myProject, filePath, revision1, revision2, autoSort);
657	+  }
658	+
659	+  private void showDiffForMergeCommit(@NotNull final AnActionEvent event, @NotNull final FilePath filePath, @NotNull final GitFileRevision rev,
660	+                                      @NotNull final Collection<String> parents) {
661	+    final AtomicBoolean fileTouched = new AtomicBoolean();
662	+    new Task.Backgroundable(myProject, "Retrieving revision changes", false) {
663	+      @Override public void run(@NotNull ProgressIndicator indicator) {
664	+        try {
665	+          fileTouched.set(wasFileTouched(rev, filePath));
666	+        }
667	+        catch (VcsException e) {
668	+          LOG.info("Error happened while executing git show " + rev + ":" + filePath, e);
669	+          VcsBalloonProblemNotifier.showOverVersionControlView(GitDiffFromHistoryHandler.this.myProject, e.getMessage(), MessageType.ERROR);
670	+        }
671	+      }
672	+
673	+      @Override
674	+      public void onSuccess() {
675	+        if (fileTouched.get()) {
676	+          String message = filePath.getName() + " did not change in this merge commit";
677	+          VcsBalloonProblemNotifier.showOverVersionControlView(GitDiffFromHistoryHandler.this.myProject, message, MessageType.INFO);
678	+        }
679	+        showPopup(event, rev, filePath, parents);
680	+      }
681	+    }.queue();
682	+  }
683	+
684	+  private void showPopup(@NotNull AnActionEvent event, @NotNull GitFileRevision rev, @NotNull FilePath filePath,
685	+                         @NotNull Collection<String> parents) {
686	+    ActionGroup parentActions = createActionGroup(rev, filePath, parents);
687	+    DataContext dataContext = SimpleDataContext.getProjectContext(myProject);
688	+    ListPopup popup = JBPopupFactory.getInstance().createActionGroupPopup("Choose parent to compare", parentActions, dataContext,
689	+                                                                          JBPopupFactory.ActionSelectionAid.NUMBERING, true);
690	+    showPopupInBestPosition(popup, event, dataContext);
691	+  }
692	+
693	+  private static void showPopupInBestPosition(@NotNull ListPopup popup, @NotNull AnActionEvent event, @NotNull DataContext dataContext) {
694	+    if (event.getInputEvent() instanceof MouseEvent) {
695	+      if (!event.getPlace().equals(ActionPlaces.UPDATE_POPUP)) {
696	+        popup.show(new RelativePoint((MouseEvent)event.getInputEvent()));
697	+      }
698	+      else { // quick fix for invoking from the context menu: coordinates are calculated incorrectly there.
699	+        popup.showInBestPositionFor(dataContext);
700	+      }
701	+    }
702	+    else {
703	+      popup.showInBestPositionFor(dataContext);
704	+    }
705	+  }
706	+
707	+  @NotNull
708	+  private ActionGroup createActionGroup(@NotNull GitFileRevision rev, @NotNull FilePath filePath, @NotNull Collection<String> parents) {
709	+    Collection<AnAction> actions = new ArrayList<AnAction>(2);
710	+    for (String parent : parents) {
711	+      actions.add(createParentAction(rev, filePath, parent));
712	+    }
713	+    return new DefaultActionGroup(ArrayUtil.toObjectArray(actions, AnAction.class));
714	+  }
715	+
716	+  @NotNull
717	+  private AnAction createParentAction(@NotNull GitFileRevision rev, @NotNull FilePath filePath, @NotNull String parent) {
718	+    return new ShowDiffWithParentAction(filePath, rev, parent);
719	+  }
720	+
721	+  private void showDiffWithParent(@NotNull VcsFileRevision revision, @NotNull FilePath filePath, @NotNull Collection<String> parents) {
722	+    VcsFileRevision parentRevision;
723	+    if (parents.size() == 1) {
724	+      String parent = parents.iterator().next();
725	+      parentRevision = makeRevisionFromHash(filePath, parent);
726	+    }
727	+    else {
728	+      parentRevision = VcsFileRevision.NULL;
729	+    }
730	+    doShowDiff(filePath, parentRevision, revision, false);
731	+  }
732	+
733	+  @NotNull
734	+  private GitFileRevision makeRevisionFromHash(@NotNull FilePath filePath, @NotNull String hash) {
735	+    return new GitFileRevision(myProject, filePath, new GitRevisionNumber(hash), false);
736	+  }
737	+
738	+  private boolean wasFileTouched(@NotNull GitFileRevision rev, @NotNull FilePath path) throws VcsException {
739	+    VirtualFile file = path.getVirtualFile();
740	+    LOG.assertTrue(file != null, "VirtualFile can't be null for " + path); // we clicked on a file and asked its history => VF must exist.
741	+    GitRepository repository = myRepositoryManager.getRepositoryForFile(file);
742	+    LOG.assertTrue(repository != null, "Repository is null for " + file);
743	+    GitCommandResult result = myGit.show(repository, rev + ":" + path);
744	+    if (result.success()) {
745	+      return isFilePresentInOutput(repository, path, result.getOutput());
746	+    }
747	+    throw new VcsException(result.getErrorOutputAsJoinedString());
748	+  }
749	+
750	+  private static boolean isFilePresentInOutput(@NotNull GitRepository repository, @NotNull FilePath path, @NotNull List<String> output) {
751	+    String relativePath = FileUtil.getRelativePath(repository.getRoot().getPath(), path.getPath(), '/');
752	+    for (String line : output) {
753	+      if (line.startsWith("---") || line.startsWith("+++")) {
754	+        if (line.contains(relativePath)) {
755	+          return true;
756	+        }
757	+      }
758	+    }
759	+    return false;
760	+  }
761	+
762	+  private class ShowDiffWithParentAction extends AnAction {
763	+
764	+    @NotNull private final FilePath myFilePath;
765	+    @NotNull private final GitFileRevision myRevision;
766	+    @NotNull private final String myParentRevision;
767	+
768	+    public ShowDiffWithParentAction(@NotNull FilePath filePath, @NotNull GitFileRevision rev, @NotNull String parent) {
769	+      super(GitUtil.getShortHash(parent));
770	+      myFilePath = filePath;
771	+      myRevision = rev;
772	+      myParentRevision = parent;
773	+    }
774	+
775	+    @Override
776	+    public void actionPerformed(AnActionEvent e) {
777	+      doShowDiff(myFilePath, makeRevisionFromHash(myFilePath, myParentRevision), myRevision, false);
778	+    }
779	+
780	+    @Override
781	+    public void update(AnActionEvent e) {
782	+
783	+    }
784	+  }
785	+}
